update inbox_items i set created_at = r.created_at from feed_reactions r
  where i.kind='reaction' and i.actor_id=r.user_id and i.subject_id::text=r.target_id and r.target_id in (select id::text from activities where provider='qa_demo');
update inbox_items i set created_at = c.created_at from feed_comments c
  where i.kind='comment' and i.actor_id=c.user_id and i.subject_id::text=c.target_id and c.target_id in (select id::text from activities where provider='qa_demo');
update inbox_items set read_at = created_at + interval '2 hours' where read_at is null and created_at < now() - interval '7 days' and user_id in (select id from users where email like 'qaworld-%' or id='4f143d76-cbac-4c84-a88f-3f8cb0111a28');
alter table league_messages enable trigger league_messages_guard_update;
